<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>商户档案</h2><p>查看当前有效经营档案；待审资料在申请审核中处理。</p></div></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data"/><div class="ui-search"><label>店铺／主体名称<Input v-model="q" maxlength="100" placeholder="搜索名称" @on-enter="search"/></label><label>经营状态<Select v-model="state" clearable><Option value="OPEN">营业中</Option><Option value="CLOSED">已关闭</Option></Select></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><div class="ui-toolbar"><span>共 {{total}} 个商户</span><Button @click="reload">刷新当前页</Button></div><Table class="s1-list-table" v-compact-table :columns="columns" :data="records" :loading="loading" no-data-text="没有符合条件的商户"><template slot="name" slot-scope="{row}"><button class="ui-link ui-primary-name" @click="detail(row.id)">{{row.storeName}}</button></template><template slot="state" slot-scope="{row}"><StatusTag :value="row.state"/></template><template slot="id" slot-scope="{row}"><span class="ui-meta">{{row.id}} · v{{row.version}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">查看档案</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="changePage"/></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';const keys=['q','state'];export default {mixins:[page],components:{PageStatus,StatusTag},data:()=>({q:'',state:'',columns:[{title:'商户名称',slot:'name',minWidth:190},{title:'主体名称',key:'legalName',minWidth:220,tooltip:true},{title:'负责人',key:'ownerName',minWidth:140},{title:'经营状态',slot:'state',width:120},{title:'编号／版本',slot:'id',minWidth:220},{title:'操作',slot:'operations',width:120}]}),mounted(){this.initializeList(keys);this.reload();},methods:{reload(){return this.load('/stores',{q:this.q||undefined,state:this.state||undefined},true);},search(){this.page=1;this.remember(keys);this.reload();},reset(){this.q='';this.state='';this.search();},changePage(v){this.page=v;this.remember(keys);this.reload();}}};</script>
